import random

def deposit():
    amount = input('Enter deposit amount: ')
    return int(amount)

def get_number_of_lines():
    lines = input('How many lines (1-3)? ')
    return int(lines)

def get_bet():
    bet = input('Bet per line: ')
    return int(bet)

def get_slot_machine_spin():
    symbols = ['A', 'B', 'C']
    return [[random.choice(symbols) for _ in range(3)] for _ in range(3)]

def main():
    bal = deposit()
    lines = get_number_of_lines()
    bet = get_bet()
    spin = get_slot_machine_spin()
    print(f'Balance: {bal}, Lines: {lines}, Bet: {bet}')
    for row in zip(*spin):
        print(' | '.join(row))

if __name__ == "__main__":
    main()

